import {standingArt} from './cast36.js';
import {HEROES,currentNode} from './engine.js';
import {NEW_ART} from './condition-ui.js';
import {icon} from './presentation-ui.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={codex:'ARCHIVE', 'codex-ally':'PERSONNEL ARCHIVE','codex-enemy':'HOSTILE ARCHIVE','large-art':'ILLUSTRATION',status:'PERSONNEL','lobby-personnel':'COMBATANT & PARTNER ARCHIVE',settings:'PREFERENCES','pause-menu':'EXPEDITION MENU',shop:'KOMANIYA EXPRESS',formation:'FAVONIUS SUPPORT',upgrades:'TACTICAL INSIGHT','upgrade-detail':'TACTICAL INSIGHT',pile:'DECK ARCHIVE',route:'EXPEDITION LOG','care-select':'BY THE EMBERS','care-dialogue':'BY THE EMBERS'};
const compact=new Set(['confirm','challenge','recruit-notice','import-text']);
export function surfaceMarkup(title,body,kind=''){
 if(kind==='media-viewer')return `<div class="media-shade"><section class="media-viewer" data-surface="media-viewer" role="dialog" aria-modal="true" aria-label="${esc(title)}" tabindex="-1"><button class="surface-close" data-action="close" aria-label="닫기" title="닫기 (Esc)">×</button>${body}</section></div>`;
 const dialogue=kind==='care-dialogue',showTitle=['pause-menu','route'].includes(kind);
 return `<div class="modal-shade modern-shade ${dialogue?'dialogue-shade':''}"><section class="modal modern-surface ${compact.has(kind)?'surface-compact':''} ${dialogue?'surface-dialogue':''}" data-surface="${esc(kind)}" role="dialog" aria-modal="true" aria-label="${esc(title)}" tabindex="-1"><header class="surface-header ${showTitle?'':'surface-headerless'}">${showTitle?`<div><small class="surface-kicker">${labels[kind]||'TEYVAT DEFENSE · EMBERS'}</small><h2>${esc(title)}</h2></div>`:''}<button class="surface-close" data-action="close" aria-label="닫기" title="닫기 (Esc)"><span aria-hidden="true">×</span></button></header><div class="surface-content">${body}</div></section></div>`;
}
export function pauseMarkup(s){
 const title=s.phase==='title',party=title?['lohen']:s.party;
 const items=[['계속하기','close',title?'시작 화면으로 돌아갑니다':'원정으로 돌아갑니다','play','tile-main'],['환경설정','settings','소리와 연출, 저장 기록','gear',''],['도감','codex','함께한 이들과 마주한 흔적','book',''],['타이틀로','title','시작 화면으로 돌아갑니다','home','tile-quiet']];
 const stats=title?'':`<dl class="menu-stats"><div><dt>공용 체력</dt><dd>${s.hp}<small> / ${s.maxHp}</small></dd></div><div><dt>보유 모라</dt><dd>${s.gold}</dd></div><div><dt>전선 기록</dt><dd>${s.collection.endings.length}</dd></div></dl>`;
 return `<div class="expedition-menu"><nav class="pause-menu" aria-label="메뉴"><p class="menu-intro">불빛이 머무는 동안</p>${items.map(([name,action,desc,ic,cls])=>`<button data-action="${action}" class="menu-tile ${cls}"><span class="tile-icon">${icon(ic)}</span><span class="tile-text"><span>${name}</span><small>${desc}</small></span><i aria-hidden="true">›</i></button>`).join('')}</nav><aside class="menu-overview" style="--party:${party.length}"><div class="menu-stage" aria-hidden="true"><b class="menu-slash"></b><div class="menu-party-art">${party.map((id,i)=>`<img src="${standingArt(id)}" alt="" style="--i:${i};--c:${HEROES[id].color}">`).join('')}</div></div><div class="menu-location"><small>서풍 원정대 · ${title?'대기 중':'원정 중'}</small><h3>${esc(title?'바람이 닿는 곳에':currentNode(s).name)}</h3><p>${title?'아직 남아 있는 불빛.':party.map(id=>`<span style="--c:${HEROES[id].color}">${HEROES[id].name}</span>`).join('')}</p>${stats}</div></aside></div>`;
}
export function settingsMarkup(p,section='audio'){
 if(!['audio','visual','save'].includes(section))section='audio';
 const range=(name,id,value,step='.01')=>`<label class="preference-row"><span>${name}</span><div><input type="range" id="${id}" min="0" max="1" step="${step}" value="${value}" aria-label="${name}"><output for="${id}">${Math.round(value*100)}%</output></div></label>`;
 const toggle=(name,id,on,desc)=>`<label class="preference-row"><span>${name}<small>${desc}</small></span><input type="checkbox" id="${id}" ${on?'checked':''}></label>`;
 const panels={audio:`<h3>소리</h3><p class="preference-description">불빛과 바람, 전투의 소리.</p><div class="audio-settings">${range('전체 음량','volume',p.volume)}${range('배경 음악','music-volume',p.music)}${range('효과음','sfx-volume',p.sfx)}</div>`,visual:`<h3>연출</h3><p class="preference-description">원정의 속도와 화면 효과를 조정합니다.</p>${toggle('짧은 연출 / 빠른 진행','fast',p.fast,'카드와 스킬 연출을 간결하게 표시합니다.')}${toggle('피격 시 화면 흔들림','shake',p.shake,'타격 순간에 짧고 가벼운 흔들림을 사용합니다.')}${range('효과 발광 강도','glow',p.glow,'.05')}<p class="fineprint">기기의 동작 줄이기가 켜져 있으면 화면 흔들림과 강한 발광을 줄입니다.</p>`,save:`<h3>저장 · 안내</h3><p class="preference-description">진행 상황과 설정은 이 브라우저에 저장됩니다.</p><div class="settings-stack">${[['저장 파일 내보내기','export'],['저장 파일 가져오기','import'],['저장 텍스트로 복원','import-text'],['전투 안내','help'],['튜토리얼 다시 하기 · 다음 새 원정','replay-tutorial']].map(([name,action])=>`<button data-action="${action}">${name}<span aria-hidden="true">＋</span></button>`).join('')}</div><input type="file" id="import-file" accept="application/json" hidden><a class="qa-menu-link" href="qa.html" target="_blank" rel="noopener">테스트 · 피드백 페이지</a>`};
 return `<div class="preferences-layout"><nav class="preferences-nav" aria-label="환경설정 분류">${[['audio','소리'],['visual','연출'],['save','저장 · 안내']].map(([id,name])=>`<button data-action="settings-tab" data-section="${id}" class="${id===section?'active':''}" aria-pressed="${id===section}">${name}<span aria-hidden="true">◇</span></button>`).join('')}<button data-action="hub-menu" class="preferences-back">메뉴로</button></nav><section class="preferences-panel" aria-label="${{audio:'소리',visual:'연출',save:'저장 · 안내'}[section]}">${panels[section]}</section></div>`;
}
